#!/usr/bin/env bash
# Removes build output (bin/, obj/, TestResults/) from every project in the repo.
# Everything removed is regenerated by the next `dotnet build` / `dotnet test`.
#
# Usage:
#   scripts/clean.sh            # delete
#   scripts/clean.sh --dry-run  # only list what would be deleted
set -euo pipefail

dry_run=false
case "${1:-}" in
  "") ;;
  -n|--dry-run) dry_run=true ;;
  -h|--help) sed -n '2,7p' "$0" | sed 's/^# \{0,1\}//'; exit 0 ;;
  *) echo "Unknown option: $1 (try --help)" >&2; exit 2 ;;
esac

# Always operate on the repository root, wherever the script is called from.
root="$(git -C "$(dirname "$0")" rev-parse --show-toplevel)"
cd "$root"

# Only directories git ignores, so tracked content can never be deleted.
targets=()
while IFS= read -r dir; do
  dir="${dir#./}"
  if git check-ignore -q "$dir"; then
    targets+=("$dir")
  fi
done < <(find . -path ./.git -prune -o -type d \( -name bin -o -name obj -o -name TestResults \) -print -prune)

if [ ${#targets[@]} -eq 0 ]; then
  echo "Nothing to clean."
  exit 0
fi

total_kb=$(du -sk "${targets[@]}" | awk '{s += $1} END {print s}')

for dir in "${targets[@]}"; do
  echo "  $dir"
done

if $dry_run; then
  echo "Dry run: would remove ${#targets[@]} directories (~$((total_kb / 1024)) MB)."
else
  rm -rf -- "${targets[@]}"
  echo "Removed ${#targets[@]} directories (~$((total_kb / 1024)) MB)."
fi
